   797  otError Leader::AddNetworkData(uint8_t *aTlvs, uint8_t aTlvsLength, uint8_t *aOldTlvs, uint8_t aOldTlvsLength)
   798  {
   799  #if !OPENTHREAD_ENABLE_SERVICE
   800      OT_UNUSED_VARIABLE(aOldTlvs);
   801      OT_UNUSED_VARIABLE(aOldTlvsLength);
   802  #endif
   803
   804      otError         error = OT_ERROR_NONE;
   805      NetworkDataTlv *cur   = reinterpret_cast<NetworkDataTlv *>(aTlvs);
   806      NetworkDataTlv *end   = reinterpret_cast<NetworkDataTlv *>(aTlvs + aTlvsLength);
   807
   808      while (cur < end)
   809      {
   810          VerifyOrExit((cur + 1) <= end && cur->GetNext() <= end, error = OT_ERROR_PARSE);
   811
   812          switch (cur->GetType())
   813          {
   814          case NetworkDataTlv::kTypePrefix:
   815              SuccessOrExit(error = AddPrefix(*static_cast<PrefixTlv *>(cur)));
   816              otDumpDebgNetData("add prefix done", mTlvs, mLength);
   817              break;
   818
   819  #if OPENTHREAD_ENABLE_SERVICE
   820
   821          case NetworkDataTlv::kTypeService:
   822              SuccessOrExit(error = AddService(*static_cast<ServiceTlv *>(cur), aOldTlvs, aOldTlvsLength));
   823              otDumpDebgNetData("add service done", mTlvs, mLength);
   824              break;
   825  #endif
   826
   827          default:
   828              break;
   829          }
   830
   831          cur = cur->GetNext();
   832      }
   833
   834      otDumpDebgNetData("add done", mTlvs, mLength);
   835
   836  exit:
   837      return error;
   838  }
