   840  otError Leader::AddPrefix(PrefixTlv &aPrefix)
   841  {
   842      otError         error = OT_ERROR_NONE;
   843      NetworkDataTlv *cur;
   844      NetworkDataTlv *end;
   845
   846      VerifyOrExit(aPrefix.IsValid(), error = OT_ERROR_PARSE);
   847      cur = aPrefix.GetSubTlvs();
   848      end = aPrefix.GetNext();
   849
   850      while (cur < end)
   851      {
   852          VerifyOrExit((cur + 1) <= end && cur->GetNext() <= end, error = OT_ERROR_PARSE);
   853
   854          switch (cur->GetType())
   855          {
   856          case NetworkDataTlv::kTypeHasRoute:
   857              SuccessOrExit(error = AddHasRoute(aPrefix, *static_cast<HasRouteTlv *>(cur)));
   858              break;
   859
   860          case NetworkDataTlv::kTypeBorderRouter:
   861              SuccessOrExit(error = AddBorderRouter(aPrefix, *static_cast<BorderRouterTlv *>(cur)));
   862              break;
   863
   864          default:
   865              break;
   866          }
   867
   868          cur = cur->GetNext();
   869      }
   870
   871  exit:
   872      return error;
   873  }
